1	import { useMemo } from 'react';
2	import { useMiaActions } from '@/hooks/useMiaActions';
3	import type { MiaActionHandler } from '@/types/mia';
4	
5	export interface EstoqueMiaInterface {
6	  setSelectedSector: (v: string) => void;
7	  setSelectedStatus: (v: string) => void;
8	  setSearchTerm: (v: string) => void;
9	  setShowHidden: (v: boolean) => void;
10	  toggleItemExpand: (id: string) => void;
11	  items: any[];
12	}
13	
14	export function useMiaEstoqueActions(iface: EstoqueMiaInterface): void {
15	  const {
16	    setSelectedSector,
17	    setSelectedStatus,
18	    setSearchTerm,
19	    setShowHidden,
20	    toggleItemExpand,
21	    items,
22	  } = iface;
23	
24	  const handlers = useMemo<Record<string, MiaActionHandler>>(() => ({
25	    estoque_filter: {
26	      id: 'estoque_filter',
27	      description: 'Aplicar filtros no estoque (setor, status, busca, mostrar ocultos)',
28	      execute: (data) => {
29	        if (!data) return;
30	        if (data.sector !== undefined) setSelectedSector(data.sector);
31	        if (data.status !== undefined) setSelectedStatus(data.status);
32	        if (data.searchTerm !== undefined) setSearchTerm(data.searchTerm);
33	        if (data.search !== undefined) setSearchTerm(data.search);
34	        if (data.showHidden !== undefined) setShowHidden(Boolean(data.showHidden));
35	      },
36	    },
37	
38	    estoque_expand: {
39	      id: 'estoque_expand',
40	      description: 'Expandir detalhes/lotes de um produto no estoque',
41	      execute: (data) => {
42	        if (data?.product_id) {
43	          toggleItemExpand(String(data.product_id));
44	        } else if (data?.product_name) {
45	          const item = items.find(
46	            (i: any) => i.produto_nome?.toLowerCase().includes(data.product_name.toLowerCase())
47	          );
48	          if (item) toggleItemExpand(String(item.produto_id));
49	        }
50	      },
51	    },
52	
53	    estoque_toggle_hidden: {
54	      id: 'estoque_toggle_hidden',
55	      description: 'Mostrar ou ocultar produtos indisponíveis na visualização',
56	      execute: (data) => {
57	        if (data?.show !== undefined) setShowHidden(!!data.show);
58	        else setShowHidden(true);
59	      },
60	    },
61	
62	    clear_filters: {
63	      id: 'clear_filters',
64	      description: 'Limpar todos os filtros do estoque',
65	      execute: () => {
66	        setSelectedSector('all');
67	        setSelectedStatus('all');
68	        setSearchTerm('');
69	        setShowHidden(false);
70	      },
71	    },
72	  }), [
73	    setSelectedSector,
74	    setSelectedStatus,
75	    setSearchTerm,
76	    setShowHidden,
77	    toggleItemExpand,
78	    items,
79	  ]);
80	
81	  useMiaActions('/visualizacao-estoque', handlers);
82	}
